Method.Implementation:
  $$$TRACE("Inside Select Method")  
  #dim tSC As %Status=$$$OK
  set lpi=pRequest.StringValue
  $$$TRACE("LPI:"_lpi)
  set pResponse = ##class(Ens.StringResponse).%New()
  set pResponse.StringValue=""
  // So this get all the records
  set pRes = ##class(EnsLib.SQL.Snapshot).%New()
  set pRes.MaxRowsToGet = -1
  try {
	set tSQL = "SELECT * FROM empi.dbo.LU_EMPI WHERE LPI=?" 
	//set tSQL = "SELECT format(REL_CREATED_DT,'yyyy-MM-dd hh:mm:ss') FROM empi.dbo.LU_EMPI WHERE LPI=?" 
	set ioParms=1
	set ioParms(1)=lpi
	set ioParms(1,"SqlType")=12

 	set tSC = ..Adapter.ExecuteQueryParmArray(.pRes,tSQL,.ioParms)


	if $$$ISOK(tSC)	{
		If ($ISOBJECT(pRes)&&(pRes.RowCount>0)){
			$$$TRACE("Retrieve REL_CREATED_DT from the Response")
			set rowNum=pRes.Next(.sc)
			$$$TRACE("Error Status"_sc)
			if ($$$ISERR(sc)){
				$$$TRACE("Error Reading result set")
				set tSC=$$$ERROR("Error Reading Result set")
			}else{
				set ldt=pRes.Get("REL_CREATED_DT")
		        $$$TRACE("Last Created_DT:"_ldt)
				set pResponse.StringValue = ldt
			}
		}
	}
	else
	{
		set pResponse.StringValue = "Failed"
		$$$TRACE("Failed to execute Query:"_tSQL)	
	}
  } 
  Catch eException {
       $$$TRACE("Inside Catch")
 	   set errTxt = $System.Status.GetErrorText(%objlasterror)
       $$$LOGERROR("Exception when check add/update LU_EMPI table: " _errTxt _ ", Excp:" _ eException.Name _ " " _ eException.Code _ " " _ eException.Location_" for Lpi: "_lpi)
       $$$LOGERROR($ZERROR)
       set tSC=0
  }

  Quit tSC


  $$$TRACE("Inside Update Method")
	//quit $$$OK

  d ..Adapter.SetAutoCommit(0)

  #dim tSC As %Status=$$$OK
  Set pResponse=##class(Ens.StringContainer).%New()
  set pResponse.StringValue="No of Rows affected"
  Set empiRequest=##class(Ens.StringContainer).%New()
  set empiRequest.StringValue=pRequest.Lpi
  try {
	set tSc = ..AddOrUpdate(empiRequest, .response)
	if (('$ISOBJECT(response)) || (response.StringValue="")){
		set tSC=..AddEmpi(pRequest,.pResponse)
	}
	elseif(response.StringValue'="Failed") {
		set lastDt=response.StringValue
		$$$TRACE("lastDt: "_lastDt_" NewDT: "_pRequest.processedDtTm)
		if $ZDATETIMEH(pRequest.processedDtTm,3,,3) < $ZDATETIMEH(lastDt_"00",3,,3)  {
		  if pRequest.Empi=pRequest.oldEmpi {
		    set tSC=..UpdateEmpi(pRequest,.pResponse)
		  }
		  else {
		    set tSC=..UpdateLpi(pRequest,.pResponse)
		  }
		}
		Else {
		  $$$TRACE("Data is not new, Skip update...")
		}
	}
	else {
	   $$$TRACE("Check data failed...")
	}
  } 
  Catch eException {
       $$$TRACE("Inside Catch")
 	   set errTxt = $System.Status.GetErrorText(%objlasterror)
       $$$LOGERROR("Exception when update empi.dbo.lu_empi table: " _errTxt _ ", Excp:" _ eException.Name _ " " _ eException.Code _ " " _ eException.Location_" for Lpi: "_pRequest.Lpi)
       $$$LOGERROR($ZERROR)
  }
  If $$$ISOK(tSC){
		d ..Adapter.Commit()  
  }Else{
		d ..Adapter.Rollback() 
  }	

	Quit tSC

Set pResponse=##class(Ens.StringContainer).%New() set pResponse.StringValue="No Of Rows affected" $$$TRACE("Inside UpdateEmpi Method") set tSQL= "UPDATE empi.dbo.lu_empi set EMPI=?,REL_CREATED_DT=?,DATESTAMP=? WHERE Lpi=?"
