if ($$$ISERR(tSC)) { set errText=" Error when insert data to empi.dbo.lu_empi table for empi: "_pRequest.Lpi $$$TRACE("Error when insert data to empi.dbo.lu_empi table for empi: "_pRequest.Lpi_", "_$System.Status.GetErrorText(tSC)) Set tSC = $$$ERROR($System.Status.GetErrorCodes(tSC),$System.Status.GetErrorText(tSC)_":"_errText) }
Quit tSC

Set pResponse=##class(Ens.StringContainer).%New() set pResponse.StringValue="No Of Rows affected" $$$TRACE("Inside UpdateEmpi Method") set tSQL= "UPDATE empi.dbo.lu_empi set LPI=?,REL_CREATED_DT=?,DATESTAMP=? WHERE EMPI=?"
