if ($$$ISERR(tSC)) { set errText=" Error when insert data to empi.dbo.lu_empi table for lpi: "_pRequest.Empi $$$TRACE("Error when insert data to empi.dbo.lu_empi table for lpi: "_pRequest.Empi_", "_$System.Status.GetErrorText(tSC)) Set tSC = $$$ERROR($System.Status.GetErrorCodes(tSC),$System.Status.GetErrorText(tSC)_":"_errText) }
